<script setup>
import { Head, router, useForm } from '@inertiajs/vue3'

const props = defineProps({ eventos: Object, filtros: Object })
const formulario = useForm({ nivel: props.filtros.nivel ?? '', servico: props.filtros.servico ?? '', requisicao: props.filtros.requisicao ?? '', de: props.filtros.de ?? '', ate: props.filtros.ate ?? '' })
function filtrar() { formulario.get('/admin/auditoria', { preserveState: true, replace: true }) }
</script>

<template>
  <Head title="Auditoria administrativa" />
  <main class="min-h-screen bg-slate-50 px-4 py-6 sm:px-8 sm:py-10"><div class="mx-auto max-w-6xl">
    <header class="flex flex-wrap items-center justify-between gap-3"><div><a href="/admin" class="text-sm font-semibold text-blue-700">← Painel global</a><h1 class="mt-2 text-2xl font-bold text-slate-950">Auditoria e eventos de segurança</h1><p class="mt-1 text-sm text-slate-600">Eventos estruturados, paginados e sem credenciais ou conteúdo privado. Não são exibidos arquivos brutos de log.</p></div></header>
    <form class="mt-5 grid gap-3 rounded-xl border border-slate-200 bg-white p-4 shadow-sm sm:grid-cols-2 lg:grid-cols-6" @submit.prevent="filtrar"><label class="grid gap-1 text-sm font-medium text-slate-700">Nível<select v-model="formulario.nivel" class="min-h-10 rounded-lg border-slate-300"><option value="">Todos</option><option value="info">Informação</option><option value="aviso">Aviso</option><option value="erro">Erro</option></select></label><label class="grid gap-1 text-sm font-medium text-slate-700">Serviço<input v-model="formulario.servico" maxlength="100" class="min-h-10 rounded-lg border-slate-300 px-2"></label><label class="grid gap-1 text-sm font-medium text-slate-700 sm:col-span-2">ID da requisição<input v-model="formulario.requisicao" maxlength="100" class="min-h-10 rounded-lg border-slate-300 px-2"></label><label class="grid gap-1 text-sm font-medium text-slate-700">De<input v-model="formulario.de" type="date" class="min-h-10 rounded-lg border-slate-300 px-2"></label><label class="grid gap-1 text-sm font-medium text-slate-700">Até<input v-model="formulario.ate" type="date" class="min-h-10 rounded-lg border-slate-300 px-2"></label><button class="min-h-10 rounded-lg bg-blue-600 px-4 font-semibold text-white sm:col-span-2 lg:col-span-6">Filtrar eventos</button></form>
    <section class="mt-4 grid gap-3"><article v-for="evento in eventos.data" :key="evento.id" class="rounded-xl border border-slate-200 bg-white p-4 shadow-sm"><div class="flex flex-wrap items-start justify-between gap-2"><div><h2 class="font-semibold text-slate-950">{{ evento.acao }}</h2><p class="mt-1 text-sm text-slate-700">{{ evento.descricao }}</p></div><span class="rounded-full px-2.5 py-1 text-xs font-semibold" :class="evento.nivel === 'erro' ? 'bg-red-50 text-red-800' : evento.nivel === 'aviso' ? 'bg-amber-50 text-amber-900' : 'bg-blue-50 text-blue-800'">{{ evento.nivel }}</span></div><dl class="mt-3 flex flex-wrap gap-x-5 gap-y-1 text-xs text-slate-500"><div><dt class="inline">Data: </dt><dd class="inline">{{ evento.criadoEm }}</dd></div><div><dt class="inline">Serviço: </dt><dd class="inline">{{ evento.servico }}</dd></div><div v-if="evento.administradorId"><dt class="inline">Administrador ID: </dt><dd class="inline">{{ evento.administradorId }}</dd></div><div v-if="evento.requisicao"><dt class="inline">Requisição: </dt><dd class="inline font-mono">{{ evento.requisicao }}</dd></div></dl><pre v-if="Object.keys(evento.metadados).length" class="mt-3 overflow-x-auto rounded bg-slate-50 p-2 text-xs text-slate-600">{{ JSON.stringify(evento.metadados, null, 2) }}</pre></article><p v-if="!eventos.data.length" class="rounded-xl border border-dashed border-slate-300 bg-white p-8 text-center text-sm text-slate-500">Nenhum evento corresponde aos filtros.</p></section>
    <nav v-if="eventos.links?.length > 3" class="mt-4 flex flex-wrap gap-2" aria-label="Paginação"><button v-for="link in eventos.links" :key="link.label" type="button" :disabled="!link.url" class="min-h-10 rounded-lg border px-3 text-sm" :class="link.active ? 'border-blue-600 bg-blue-600 text-white' : 'border-slate-300 bg-white text-slate-700 disabled:opacity-50'" @click="link.url && router.visit(link.url, { preserveScroll: true })" v-html="link.label" /></nav>
  </div></main>
</template>
